export const bulkImportRepertoireBodySongsItemBpmMin = 30;
export const bulkImportRepertoireBodySongsItemBpmMax = 300;

export const bulkImportRepertoireBodySongsItemLastScheduledDateRegExp =
  new RegExp("^[0-9]{4}-[0-9]{2}-[0-9]{2}$");

export const BulkImportRepertoireBody = zod.object({
  songs: zod
    .array(
      zod.object({
        title: zod.string().min(1),
        artist: zod.string().optional(),
        style: zod.string().optional(),
        bpm: zod
          .number()
          .min(bulkImportRepertoireBodySongsItemBpmMin)
          .max(bulkImportRepertoireBodySongsItemBpmMax)
          .optional()
          .describe(
            "Optional tempo in beats per minute. Helps the AI pick fast songs for upbeat slots and slower songs for reflective ones.",
          ),
        key: zod
          .string()
          .optional()
          .describe(
            'Optional musical key (e.g. \"G\", \"Db\"). Pulled from CSV imports; stored on `content.key`.',
          ),
        ccli: zod
          .string()
          .optional()
          .describe(
            "Optional CCLI license number. Stored on `content.ccli` for traceability; not currently surfaced in the UI.",
          ),
        notes: zod
          .string()
          .optional()
          .describe(
            "Optional free-text notes from a CSV import. Stored on `content.notes`.",
          ),
        arrangementNotes: zod
          .string()
          .optional()
          .describe(
            "Optional free-text notes for the chosen arrangement (BPM\/key\/length). Stored on `content.arrangementNotes`.",
          ),
        lastScheduledDate: zod
          .string()
          .regex(bulkImportRepertoireBodySongsItemLastScheduledDateRegExp)
          .optional()
          .describe(
            "Optional ISO YYYY-MM-DD date the song was last scheduled. Stored verbatim on content.lastScheduledDate. Useful for ranking under-used songs later. The pattern enforces ISO format at the Zod layer; clients must normalize free-form dates (e.g. 'March 29, 2026') to ISO before submitting and OMIT malformed values rather than passing them through. We avoid format: date so the value stays a string end-to-end (no Date\/string coercion in the contract).",
          ),
        tags: zod.array(zod.string()).optional(),
      }),
    )
    .min(1),
});

